local generator=require("lib.generator")local codec=require("lib.codec")local M={}M.CONFIG_NAME="braincloud_config.lua"M.DEFAULT_SERVER_URL="https://api.braincloudservers.com/dispatcherv2"M.DEFAULT_APP_VERSION="1.0.0"local SEP=package.config:sub(1,1)local function exists(path)local f=io.open(path,"rb")if f then f:close()return true end return false end local function readFile(path)local f=io.open(path,"rb")if not f then return nil end local s=f:read("*a")f:close()return s end function M.join(a,b)if a:sub(-1)=="/"or a:sub(-1)=="\\"then return a..b end return a.."/"..b end function M.dirname(path)return path:match("^(.*)[/\\][^/\\]*$")or"."end function M.basename(path)return path:match("([^/\\]+)$")or path end function M.defaultOutput(projectDir)return M.join(projectDir,M.CONFIG_NAME)end function M.read(file)local data=generator.dataOf(readFile(file))if not data then return nil end local ok,cfg=pcall(codec.decode,data)if not ok then return nil end return{appId=cfg.appId,serverUrl=cfg.serverUrl,appVersion=cfg.appVersion}end local function mkdirs(dir)if SEP=="\\"then os.execute('mkdir "'..dir..'" 2>nul')else os.execute("mkdir -p '"..dir:gsub("'","'\\''").."'")end end function M.write(file,cfg)mkdirs(M.dirname(file))local f=assert(io.open(file,"wb"))f:write(generator.generate({appId=cfg.appId,appValue=cfg.appValue,serverUrl=cfg.serverUrl or M.DEFAULT_SERVER_URL,appVersion=cfg.appVersion or M.DEFAULT_APP_VERSION,}))f:close()end function M.rewrite(file,serverUrl,appVersion)local data=generator.dataOf(readFile(file))if not data then return false end local current=codec.decode(data)M.write(file,{appId=current.appId,appValue=current.appValue,serverUrl=serverUrl,appVersion=appVersion})return true end local function repoRoot(file)local dir=M.dirname(file)while true do if exists(M.join(dir,".git".."/HEAD"))or exists(M.join(dir,".git"))then return dir end local parent=M.dirname(dir)if parent==dir or parent=="."or parent==""then return nil end dir=parent end end local function relative(root,file)local rel=file:sub(#root+2)return(rel:gsub("\\","/"))end function M.isIgnored(file)local root=repoRoot(file)local gitignore=root and readFile(M.join(root,".gitignore"))if not gitignore then return false end local rel=relative(root,file)local name=M.basename(file)for line in(gitignore.."\n"):gmatch("(.-)\r?\n")do local l=line:match("^%s*(.-)%s*$")if l==rel or l=="/"..rel or l==name or l=="**/"..name then return true end end return false end function M.ensureIgnored(file)local root=repoRoot(file)if not root or M.isIgnored(file)then return end local path=M.join(root,".gitignore")local existing=readFile(path)or""local prefix=(existing~=""and existing:sub(-1)~="\n")and"\n"or""local f=io.open(path,"ab")if f then f:write(prefix.."# brainCloud app config (generated)\n/"..relative(root,file).."\n")f:close()end end function M.mtime(file)local p=io.popen((SEP=="\\")and('forfiles /p "'..M.dirname(file)..'" /m "'..M.basename(file)..'" /c "cmd /c echo @fdate @ftime" 2>nul')or("stat -f %m '"..file.."' 2>/dev/null || stat -c %Y '"..file.."' 2>/dev/null"))if not p then return 0 end local out=p:read("*l")p:close()return(tonumber(out or"")or 0)*1000 end return M
